class Pattern:
    def __init__(
        self, name: str | None, value: list[str] | str | int | None = None
    ) -> None:
        self._name, self.value = name, value

    @property
    def name(self) -> str | None:
        return self._name

    def __eq__(self, other) -> bool:
        return repr(self) == repr(other)

    def __hash__(self) -> int:
        return hash(repr(self))


def transform(pattern: BranchPattern) -> Either:
    """Expand pattern into an equivalent form with a single top-level Either."""
    result = []
    groups = [[pattern]]
    while groups:
        children = groups.pop(0)
        parents = [Required, NotRequired, OptionsShortcut, Either, OneOrMore]
        if any(t in map(type, children) for t in parents):
            child = [c for c in children if type(c) in parents][0]
            children.remove(child)
            if type(child) is Either:
                for c in child.children:
                    groups.append([c] + children)
            elif type(child) is OneOrMore:
                groups.append(child.children * 2 + children)
            else:
                groups.append(child.children + children)
        else:
            result.append(children)
    return Either(*[Required(*entry) for entry in result])


TSingleMatch = tuple[Union[int, None], Union["LeafPattern", None]]


class LeafPattern(Pattern):
    """Leaf/terminal node of a pattern tree."""

    def __repr__(self) -> str:
        return "%s(%r, %r)" % (self.__class__.__name__, self.name, self.value)

    def single_match(self, left: list[LeafPattern]) -> TSingleMatch:
        raise NotImplementedError

    def flat(self, *types) -> list[LeafPattern]:
        return [self] if not types or type(self) in types else []

    def match(
        self, left: list[LeafPattern], collected: list[Pattern] | None = None
    ) -> tuple[bool, list[LeafPattern], list[Pattern]]:
        collected = [] if collected is None else collected
        increment: Any | None = None
        pos, match = self.single_match(left)
        if match is None or pos is None:
            return False, left, collected
        left_ = left[:pos] + left[(pos + 1) :]
        same_name = [a for a in collected if a.name == self.name]
        if type(self.value) is int and len(same_name) > 0:
            if isinstance(same_name[0].value, int):
                same_name[0].value += 1
            return True, left_, collected
        if type(self.value) is int and not same_name:
            match.value = 1
            return True, left_, collected + [match]
        if same_name and type(self.value) is list:
            if type(match.value) is str:
                increment = [match.value]
            if same_name[0].value is not None and increment is not None:
                if isinstance(same_name[0].value, type(increment)):
                    same_name[0].value += increment
            return True, left_, collected
        if not same_name and type(self.value) is list:
            if isinstance(match.value, str):
                match.value = [match.value]
            return True, left_, collected + [match]
        return True, left_, collected + [match]


class BranchPattern(Pattern):
    """Branch/inner node of a pattern tree."""

    def __init__(self, *children) -> None:
        self.children = list(children)

    def match(self, left: list[Pattern], collected: list[Pattern] | None = None) -> Any:
        raise NotImplementedError

    def fix(self) -> "BranchPattern":
        self.fix_identities()
        self.fix_repeating_arguments()
        return self

    def fix_identities(self, uniq: Any | None = None) -> None:
        flattened = self.flat()
        uniq = list(set(flattened)) if uniq is None else uniq
        for i, child in enumerate(self.children):
            if not hasattr(child, "children"):
                assert child in uniq
                self.children[i] = uniq[uniq.index(child)]
            else:
                child.fix_identities(uniq)

    def fix_repeating_arguments(self) -> "BranchPattern":
        either = [list(child.children) for child in transform(self).children]
        for case in either:
            for element in [child for child in case if case.count(child) > 1]:
                if type(element) is Argument or type(element) is Option and element.argcount:
                    if element.value is None:
                        element.value = []
                    elif type(element.value) is not list:
                        element.value = cast(str, element.value)
                        element.value = element.value.split()
                if type(element) is Command or type(element) is Option and element.argcount == 0:
                    element.value = 0
        return self

    def __repr__(self) -> str:
        return "%s(%s)" % (
            self.__class__.__name__,
            ", ".join(repr(arg) for arg in self.children),
        )

    def flat(self, *types) -> Any:
        if type(self) in types:
            return [self]
        return sum([child.flat(*types) for child in self.children], [])


class Argument(LeafPattern):
    def single_match(self, left: list[LeafPattern]) -> TSingleMatch:
        for n, pattern in enumerate(left):
            if type(pattern) is Argument:
                return n, Argument(self.name, pattern.value)
        return None, None


class Command(Argument):
    def __init__(self, name: str | None, value: bool = False) -> None:
        self._name, self.value = name, value

    def single_match(self, left: list[LeafPattern]) -> TSingleMatch:
        for n, pattern in enumerate(left):
            if type(pattern) is Argument:
                if pattern.value == self.name:
                    return n, Command(self.name, True)
                break
        return None, None


class Option(LeafPattern):
    def __init__(
        self,
        short: str | None = None,
        longer: str | None = None,
        argcount: int = 0,
        value: list[str] | str | int | None = False,
    ) -> None:
        assert argcount in (0, 1)
        self.short, self.longer, self.argcount = short, longer, argcount
        self.value = None if value is False and argcount else value

    @classmethod
    def parse(cls, option_description: str) -> "Option":
        short, longer, argcount, value = None, None, 0, False
        options, description = re.split(
            r"(?:  )|$", option_description.strip(), flags=re.M, maxsplit=1
        )
        options = options.replace(",", " ").replace("=", " ")
        for item in options.split():
            if item.startswith("--"):
                longer = item
            elif item.startswith("-"):
                short = item
            else:
                argcount = 1
        if argcount:
            matched = re.findall(r"\[default: (.*)\]", description, flags=re.I)
            value = matched[0] if matched else None
        return cls(short, longer, argcount, value)

    def single_match(self, left: list[LeafPattern]) -> TSingleMatch:
        for n, pattern in enumerate(left):
            if self.name == pattern.name:
                return n, pattern
        return None, None

    @property
    def name(self) -> str | None:
        return self.longer or self.short

    def __repr__(self) -> str:
        return "Option(%r, %r, %r, %r)" % (
            self.short,
            self.longer,
            self.argcount,
            self.value,
        )


class Required(BranchPattern):
    def match(self, left: list[Pattern], collected: list[Pattern] | None = None) -> Any:
        collected = [] if collected is None else collected
        original_collected = collected
        original_left = left
        for pattern in self.children:
            matched, left, collected = pattern.match(left, collected)
            if not matched:
                return False, original_left, original_collected
        return True, left, collected


class NotRequired(BranchPattern):
    def match(self, left: list[Pattern], collected: list[Pattern] | None = None) -> Any:
        collected = [] if collected is None else collected
        for pattern in self.children:
            _, left, collected = pattern.match(left, collected)
        return True, left, collected


class OptionsShortcut(NotRequired):
    """Marker/placeholder for [options] shortcut."""


class OneOrMore(BranchPattern):
    def match(self, left: list[Pattern], collected: list[Pattern] | None = None) -> Any:
        assert len(self.children) == 1
        collected = [] if collected is None else collected
        original_collected = collected
        original_left = left
        last_left = None
        matched = True
        times = 0
        while matched:
            matched, left, collected = self.children[0].match(left, collected)
            times += 1 if matched else 0
            if last_left == left:
                break
            last_left = left
        if times >= 1:
            return True, left, collected
        return False, original_left, original_collected


class Either(BranchPattern):
    def match(self, left: list[Pattern], collected: list[Pattern] | None = None) -> Any:
        collected = [] if collected is None else collected
        outcomes = []
        for pattern in self.children:
            matched, _, _ = outcome = pattern.match(left, collected)
            if matched:
                outcomes.append(outcome)
        if outcomes:
            return min(outcomes, key=lambda outcome: len(outcome[1]))
        return False, left, collected


class Tokens(list):
    def __init__(
        self,
        source: list[str] | str,
        error: Type[DocoptExit] | Type[DocoptLanguageError] = DocoptExit,
    ) -> None:
        if isinstance(source, list):
            self += source
        else:
            self += source.split()
        self.error = error

    @staticmethod
    def from_pattern(source: str) -> "Tokens":
        source = re.sub(r"([\[\]\(\)\|]|\.\.\.)", r" \1 ", source)
        fragments = [s for s in re.split(r"\s+|(\S*<.*?>)", source) if s]
        return Tokens(fragments, error=DocoptLanguageError)

    def move(self) -> str | None:
        return self.pop(0) if len(self) else None

    def current(self) -> str | None:
        return self[0] if len(self) else None


def parse_longer(
    tokens: Tokens, options: list[Option], argv: bool = False, more_magic: bool = False
) -> list[Pattern]:
    """Parse long form options starting with --."""
    current_token = tokens.move()
    if current_token is None or not current_token.startswith("--"):
        raise ValueError(f"parse_longer got invalid token: {current_token}")
    longer, maybe_eq, maybe_value = current_token.partition("=")
    value = None if maybe_eq == maybe_value == "" else maybe_value
    similar = [opt for opt in options if opt.longer and longer == opt.longer]
    start_collision = (
        len(
            [
                opt
                for opt in options
                if opt.longer and longer in opt.longer and opt.longer.startswith(longer)
            ]
        )
        > 1
    )
    if argv and not len(similar) and not start_collision:
        similar = [
            opt
            for opt in options
            if opt.longer and longer in opt.longer and opt.longer.startswith(longer)
        ]
    if more_magic and not similar:
        corrected = [
            (longer, opt)
            for opt in options
            if opt.longer and levenshtein_norm(longer, opt.longer) < 0.25
        ]
        if corrected:
            print(f"NB: Corrected {corrected[0][0]} to {corrected[0][1].longer}")
        similar = [correct for (_, correct) in corrected]
    if len(similar) > 1:
        raise DocoptLanguageError(f"{longer} is not a unique prefix: {similar}?")
    if len(similar) < 1:
        argcount = 1 if maybe_eq == "=" else 0
        option = Option(None, longer, argcount)
        options.append(option)
        if tokens.error is DocoptExit:
            option = Option(None, longer, argcount, value if argcount else True)
        return [option]
    option = Option(
        similar[0].short, similar[0].longer, similar[0].argcount, similar[0].value
    )
    if option.argcount == 0:
        if value is not None:
            raise tokens.error("%s must not have an argument" % option.longer)
    else:
        if value is None:
            if tokens.current() in [None, "--"]:
                raise tokens.error("%s requires argument" % option.longer)
            value = tokens.move()
    if tokens.error is DocoptExit:
        option.value = value if value is not None else True
    return [option]


def parse_shorts(
    tokens: Tokens, options: list[Option], more_magic: bool = False
) -> list[Pattern]:
    """Parse short form options starting with -."""
    token = tokens.move()
    if token is None or not token.startswith("-") or token.startswith("--"):
        raise ValueError(f"parse_shorts got invalid token: {token}")
    left = token.lstrip("-")
    parsed: list[Pattern] = []
    while left != "":
        short, left = "-" + left[0], left[1:]
        transformations: dict[str | None, Callable[[str], str]] = {None: lambda x: x}
        if more_magic:
            transformations["lowercase"] = lambda x: x.lower()
            transformations["uppercase"] = lambda x: x.upper()
        similar: list[Option] = []
        de_abbreviated = False
        for transform_name, transform in transformations.items():
            transformed = list(set([transform(opt.short) for opt in options if opt.short]))
            no_collisions = len(
                [
                    opt
                    for opt in options
                    if opt.short and transformed.count(transform(opt.short)) == 1
                ]
            )
            if no_collisions:
                similar = [
                    opt
                    for opt in options
                    if opt.short and transform(opt.short) == transform(short)
                ]
                if similar:
                    if transform_name:
                        print(
                            f"NB: Corrected {short} to {similar[0].short} via {transform_name}"
                        )
                    break
            if not similar and more_magic:
                abbreviated = [
                    transform(opt.longer[1:3])
                    for opt in options
                    if opt.longer and not opt.short
                ] + [transform(opt.short) for opt in options if opt.short and not opt.longer]
                nonredundantly_abbreviated_options = [
                    opt for opt in options if opt.longer and abbreviated.count(short) == 1
                ]
                no_collisions = len(nonredundantly_abbreviated_options) == len(
                    abbreviated
                )
                if no_collisions:
                    for opt in options:
                        if (
                            not opt.short
                            and opt.longer
                            and transform(short) == transform(opt.longer[1:3])
                        ):
                            similar = [opt]
                            print(
                                f"NB: Corrected {short} to {similar[0].longer} via abbreviation "
                                f"(case change: {transform_name})"
                            )
                            break
                if len(similar):
                    de_abbreviated = True
                    break
        if len(similar) > 1:
            raise DocoptLanguageError(
                f"{short} is specified ambiguously {len(similar)} times"
            )
        if len(similar) < 1:
            option = Option(short, None, 0)
            options.append(option)
            if tokens.error is DocoptExit:
                option = Option(short, None, 0, True)
            parsed.append(option)
            continue
        option_short_value = None if de_abbreviated else transform(short)
        option = Option(
            option_short_value,
            similar[0].longer,
            similar[0].argcount,
            similar[0].value,
        )
        value = None
        current_token = tokens.current()
        if option.argcount != 0:
            if left == "":
                if current_token is None or current_token == "--":
                    raise tokens.error("%s requires argument" % short)
                value = tokens.move()
            else:
                value = left
                left = ""
        if tokens.error is DocoptExit:
            option.value = value if value is not None else True
        parsed.append(option)
    return parsed


def parse_pattern(source: str, options: list[Option]) -> Required:
    tokens = Tokens.from_pattern(source)
    result = parse_expr(tokens, options)
    if tokens.current() is not None:
        raise tokens.error("unexpected ending: %r" % " ".join(tokens))
    return Required(*result)


def parse_expr(tokens: Tokens, options: list[Option]) -> list[Pattern]:
    """expr ::= seq ( '|' seq )* ;"""
    result: list[Pattern] = []
    seq_0 = parse_seq(tokens, options)
    if tokens.current() != "|":
        return seq_0
    if len(seq_0) > 1:
        result.append(Required(*seq_0))
    else:
        result += seq_0
    while tokens.current() == "|":
        tokens.move()
        seq_1 = parse_seq(tokens, options)
        if len(seq_1) > 1:
            result += [Required(*seq_1)]
        else:
            result += seq_1
    return [Either(*result)]


def parse_seq(tokens: Tokens, options: list[Option]) -> list[Pattern]:
    """seq ::= ( atom [ '...' ] )* ;"""
    result: list[Pattern] = []
    while tokens.current() not in [None, "]", ")", "|"]:
        atom = parse_atom(tokens, options)
        if tokens.current() == "...":
            atom = [OneOrMore(*atom)]
            tokens.move()
        result += atom
    return result


def parse_atom(tokens: Tokens, options: list[Option]) -> list[Pattern]:
    """Parse atomic groups, options, arguments, and commands."""
    token = tokens.current()
    if not token:
        return [Command(tokens.move())]
    if token in "([":
        tokens.move()
        matching = {"(": ")", "[": "]"}[token]
        pattern = {"(": Required, "[": NotRequired}[token]
        matched_pattern = pattern(*parse_expr(tokens, options))
        if tokens.move() != matching:
            raise tokens.error("unmatched '%s'" % token)
        return [matched_pattern]
    if token == "options":
        tokens.move()
        return [OptionsShortcut()]
    if token.startswith("--") and token != "--":
        return parse_longer(tokens, options)
    if token.startswith("-") and token not in ("-", "--"):
        return parse_shorts(tokens, options)
    if token.startswith("<") and token.endswith(">") or token.isupper():
        return [Argument(tokens.move())]
    return [Command(tokens.move())]


def parse_argv(
    tokens: Tokens,
    options: list[Option],
    options_first: bool = False,
    more_magic: bool = False,
) -> list[Pattern]:
    """Parse command-line argument vector."""

    def isanumber(value: str) -> bool:
        try:
            float(value)
            return True
        except ValueError:
            return False

    parsed: list[Pattern] = []
    current_token = tokens.current()
    while current_token is not None:
        if current_token == "--":
            return parsed + [Argument(None, value) for value in tokens]
        if current_token.startswith("--"):
            parsed += parse_longer(tokens, options, argv=True, more_magic=more_magic)
        elif current_token.startswith("-") and current_token != "-" and not isanumber(
            current_token
        ):
            parsed += parse_shorts(tokens, options, more_magic=more_magic)
        elif options_first:
            return parsed + [Argument(None, value) for value in tokens]
        else:
            parsed.append(Argument(None, tokens.move()))
        current_token = tokens.current()
    return parsed


class DocSections(NamedTuple):
    before_usage: str
    usage_header: str
    usage_body: str
    after_usage: str


def parse_docstring_sections(docstring: str) -> DocSections:
    """Partition the docstring into sections around the usage block."""
    usage_pattern = r"""
    \A(?P<before_usage>(?:(?!.*\busage:).*\n)*)
    ^(?P<usage_header>.*\busage:)
    (?P<usage_body>
        (?:.*(?:\n|\Z))
        (?:[ \t].*(?:\n|\Z))*
    )
    (?P<after_usage>(?:.|\n)*)\Z
    """
    match = re.match(usage_pattern, docstring, flags=re.M | re.I | re.VERBOSE)
    if not match:
        raise DocoptLanguageError(
            'Failed to parse doc: "usage:" section (case-insensitive) not found. '
            "Check http://docopt.org/ for examples of how your doc should look."
        )
    before, header, body, after = match.groups()
    return DocSections(before, header, body, after)


def parse_options(docstring: str) -> list[Option]:
    """Parse option descriptions from help text."""
    option_start = r"""
    ^
    (?:.*options:)?
    [ \t]*
    (-\S)
    """
    parts = re.split(option_start, docstring, flags=re.M | re.I | re.VERBOSE)[1:]
    return [
        Option.parse(start + rest) for (start, rest) in zip(parts[0::2], parts[1::2])
    ]


def lint_docstring(sections: DocSections) -> None:
    """Report apparent mistakes in the docstring format."""
    if re.search("options:", sections.usage_body, flags=re.I):
        raise DocoptLanguageError(
            'Failed to parse docstring: "options:" (case-insensitive) was '
            'found in "usage:" section. Use a blank line after the usage, or '
            "start the next section without leading whitespace."
        )
    if re.search("usage:", sections.usage_body + sections.after_usage, flags=re.I):
        raise DocoptLanguageError(
            'Failed to parse docstring: More than one "usage:" '
            "(case-insensitive) section found."
        )
    if sections.usage_body.strip() == "":
        raise DocoptLanguageError(
            'Failed to parse docstring: "usage:" section is empty.'
            "Check http://docopt.org/ for examples of how your doc should look."
        )


def formal_usage(usage: str) -> str:
    program_name, *tokens = usage.split()
    return "( " + " ".join(") | (" if token == program_name else token for token in tokens) + " )"


def extras(
    default_help: bool, version: Any, options: list[Pattern], docstring: str
) -> None:
    if default_help and any(
        (opt.name in ("-h", "--help")) and opt.value
        for opt in options
        if isinstance(opt, Option)
    ):
        print(docstring.strip("\n"))
        sys.exit()
    if version and any(
        opt.name == "--version" and opt.value for opt in options if isinstance(opt, Option)
    ):
        print(version)
        sys.exit()


_INT_PATTERN = re.compile(r"^[+-]?\d+$")
_FLOAT_PATTERN = re.compile(
    r"^[+-]?(?:(?:\d+\.\d*|\.\d+)(?:[eE][+-]?\d+)?|\d+[eE][+-]?\d+)$"
)


def normalize_key(name: str) -> str:
    """Normalize a docopt key to a Python-friendly identifier."""
    if name == "--":
        return "double_dash"
    if name == "-":
        return "stdin"
    normalized = name.strip("<>").lstrip("-")
    normalized = re.sub(r"[^0-9A-Za-z_]+", "_", normalized)
    normalized = re.sub(r"_+", "_", normalized).strip("_")
    return normalized or "value"


def infer_value(value: Any) -> Any:
    """Infer ints and floats from string values while preserving docopt semantics."""
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, list):
        return [infer_value(item) for item in value]
    if isinstance(value, str):
        if _INT_PATTERN.fullmatch(value):
            return int(value)
        if _FLOAT_PATTERN.fullmatch(value):
            return float(value)
    return value


def _resolve_hook(
    mapping: Mapping[str, Any] | None,
    key: str,
) -> Any | None:
    if mapping is None:
        return None
    if key in mapping:
        return mapping[key]
    normalized = normalize_key(key)
    return mapping.get(normalized)


def _apply_converter(value: Any, converter: Converter) -> Any:
    if value is None:
        return None
    if isinstance(value, list):
        if converter in (list, tuple, set):
            return converter(value)
        return [converter(item) for item in value]
    return converter(value)


def validate_options(
    parsed: Mapping[str, Any],
    validators: Mapping[str, Validator] | None = None,
) -> ParsedOptions:
    """Validate parsed options with per-key validator callables."""
    result = ParsedOptions(parsed)
    if validators is None:
        return result
    for key, value in result.items():
        validator = _resolve_hook(validators, key)
        if validator is None:
            continue
        try:
            outcome = validator(value)
        except Exception as exc:
            raise DocoptValidationError(f"validation failed for {key!r}: {exc}") from exc
        if outcome is False:
            raise DocoptValidationError(f"validation failed for {key!r}: {value!r}")
    return result


def convert_types(
    parsed: Mapping[str, Any],
    converters: Mapping[str, Converter] | None = None,
    infer: bool = False,
    validators: Mapping[str, Validator] | None = None,
) -> "ParsedOptions":
    """Apply type conversion and validation to parsed docopt results."""
    result = ParsedOptions()
    for key, value in parsed.items():
        converter = _resolve_hook(converters, key)
        if converter is not None:
            try:
                result[key] = _apply_converter(value, converter)
            except Exception as exc:
                raise DocoptTypeError(f"failed to convert {key!r}: {exc}") from exc
        else:
            result[key] = infer_value(value) if infer else value
    return validate_options(result, validators)


class ParsedOptions(dict):
    def __repr__(self) -> str:
        return "{%s}" % ",\n ".join("%r: %r" % item for item in sorted(self.items()))

    def __getattr__(self, name: str) -> Any:
        if name in self:
            return self[name]
        for key, value in self.items():
            if isinstance(key, str) and normalize_key(key) == name:
                return value
        return None

    def as_kwargs(self) -> dict[str, Any]:
        """Return values keyed by normalized Python parameter names."""
        return {
            normalize_key(key): value for key, value in self.items() if isinstance(key, str)
        }

    def to_namespace(self) -> argparse.Namespace:
        """Return an argparse-compatible namespace."""
        return argparse.Namespace(**self.as_kwargs())

    def typed(
        self,
        converters: Mapping[str, Converter] | None = None,
        infer: bool = False,
        validators: Mapping[str, Validator] | None = None,
    ) -> "ParsedOptions":
        """Return a converted copy of the parsed options."""
        return convert_types(self, converters=converters, infer=infer, validators=validators)


def docopt(
    docstring: str,
    argv: list[str] | str | None = None,
    default_help: bool = True,
    version: Any = None,
    options_first: bool = False,
) -> ParsedOptions:
    """Parse argv based on the command-line interface described in docstring."""
    argv = sys.argv[1:] if argv is None else argv
    sections = parse_docstring_sections(docstring)
    lint_docstring(sections)
    DocoptExit.usage = sections.usage_header + sections.usage_body
    options = [
        *parse_options(sections.before_usage),
        *parse_options(sections.after_usage),
    ]
    pattern = parse_pattern(formal_usage(sections.usage_body), options)
    pattern_options = set(pattern.flat(Option))
    for options_shortcut in pattern.flat(OptionsShortcut):
        options_shortcut.children = [
            option for option in options if option not in pattern_options
        ]
    parsed_arg_vector = parse_argv(Tokens(argv), list(options), options_first)
    extras(default_help, version, parsed_arg_vector, docstring)
    matched, left, collected = pattern.fix().match(parsed_arg_vector)
    if matched and left == []:
        return ParsedOptions((arg.name, arg.value) for arg in (pattern.flat() + collected))
    if left:
        raise DocoptExit(f"Warning: found unmatched (duplicate?) arguments {left}")
    raise DocoptExit(collected=collected, left=left)


