from __future__ import annotations

import pytest

from docopt import DocoptExit
from docopt import docopt


def test_basic_command_line_parsing():
    doc = """
    Usage:
      prog.py [-h] [--version] <input> [--output=<file>]
    Options:
      -h --help         Show help.
      --version         Show version.
      --output=<file>   Output file.
    """
    result = docopt(doc, argv=["input.txt", "--output=out.txt"])
    assert result == {
        "<input>": "input.txt",
        "--output": "out.txt",
        "--help": False,
        "--version": False,
    }


def test_repeatable_arguments_and_defaults():
    doc = """
    Usage: prog.py [--repeat=<n>] <file>...
    Options:
      --repeat=<n>  Repeat count [default: 1].
    """
    result = docopt(doc, argv=["file1.txt", "file2.txt", "--repeat=3"])
    assert result == {"<file>": ["file1.txt", "file2.txt"], "--repeat": "3"}
    assert docopt(doc, argv=[]) == {"<file>": [], "--repeat": "1"}


def test_nested_subcommands():
    doc = """
    Usage:
      git add <file>...
      git commit -m <msg>
      git push [origin] [master]
    """
    result = docopt(doc, argv=["commit", "-m", "init"])
    assert result == {
        "add": False,
        "commit": True,
        "push": False,
        "<file>": None,
        "-m": True,
        "<msg>": "init",
        "origin": False,
        "master": False,
    }


def test_short_option_combination():
    doc = "Usage: prog.py [-a] [-b] [-c]"
    assert docopt(doc, argv=["-abc"]) == {"-a": True, "-b": True, "-c": True}


def test_complex_pattern_matching():
    doc = """
    Usage: prog.py (go | stop) [--speed=<s>]
    """
    result = docopt(doc, argv=["go", "--speed=10"])
    assert result == {"go": True, "stop": False, "--speed": "10"}


def test_unique_prefix_and_ambiguous_prefix_behavior():
    doc = """
    Usage: prog [options]
    Options:
      --version  Show version.
      --verbose  Verbose mode.
    """
    assert docopt(doc, argv=["--verb"]) == {"--version": False, "--verbose": True}
    with pytest.raises(DocoptExit):
        docopt(doc, argv=["--ver"])


def test_flag_counting_and_repetition():
    doc = "Usage: prog [-v -v]"
    assert docopt(doc, argv=[]) == {"-v": 0}
    assert docopt(doc, argv=["-v"]) == {"-v": 1}
    assert docopt(doc, argv=["-vv"]) == {"-v": 2}

    doc = "Usage: prog NAME..."
    assert docopt(doc, argv=["a", "b"]) == {"NAME": ["a", "b"]}


def test_mutually_exclusive_patterns():
    doc = "Usage: prog (-a|-b)"
    assert docopt(doc, argv=["-a"]) == {"-a": True, "-b": False}
    assert docopt(doc, argv=["-b"]) == {"-a": False, "-b": True}
    with pytest.raises(DocoptExit):
        docopt(doc, argv=["-a", "-b"])


def test_multi_value_default_handling():
    doc = "Usage: prog [-o <o>]...\nOptions: -o <o>  [default: x y]"
    assert docopt(doc, argv=[]) == {"-o": ["x", "y"]}


def test_posix_double_dash_support():
    doc = "usage: prog [-o] [--] <arg>\noptions: -o"
    assert docopt(doc, argv=["--", "-o"]) == {"-o": False, "--": True, "<arg>": "-o"}
    assert docopt(doc, argv=["-o", "1"]) == {"-o": True, "--": False, "<arg>": "1"}


def test_special_argument_names_and_multiple_usages():
    assert docopt("usage: prog [<input file>]", argv=["f.txt"]) == {
        "<input file>": "f.txt"
    }
    doc = "usage: prog\n       prog <a> <b>"
    assert docopt(doc, argv=["1", "2"]) == {"<a>": "1", "<b>": "2"}
    assert docopt(doc, argv=[]) == {"<a>": None, "<b>": None}

